export function isMobileBrowser({userAgent='',platform='',maxTouchPoints=0,userAgentData}={}){
 return userAgentData?.mobile===true||/Android|iPhone|iPad|iPod|IEMobile|Opera Mini/i.test(userAgent)||(platform==='MacIntel'&&maxTouchPoints>1);
}
export function mobileNoticeMarkup(){return '<h2>Mokel on mobile</h2><p>Mokel is not yet fully supported in standard mobile browsers.</p><p><strong>Mokel Mobile App — coming soon.</strong> The app is not available to download yet.</p><p>On Android, you can explore a browser that supports extensions:</p><ul class="about-list"><li><a href="https://www.quetta.net/downloads" target="_blank" rel="noopener noreferrer">Quetta</a> — supports Chromium extensions.</li><li><a href="https://www.mozilla.org/firefox/browsers/mobile/android/" target="_blank" rel="noopener noreferrer">Firefox for Android</a> — supports Firefox add-ons.</li><li><a href="https://www.microsoft.com/edge/download/insider" target="_blank" rel="noopener noreferrer">Microsoft Edge Canary</a> — experimental Android browser with custom-extension support.</li></ul><p class="small-note">Extension support alone does not guarantee that the Mokel Bridge will work. Android Bridge compatibility is still being tested. Use a desktop browser for supported Agent Mode and local PC access.</p><button class="button full" data-action="modal-close">Continue anyway</button>';}
